"""
ベルマンフォード法 (Bellman-Ford Algorithm)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
負の重みを持つ辺を含むグラフにおける単一始点最短経路問題 (SSSP)。
負閉路の検出が可能。O(V * E)。

【引数・戻り値】
- bellman_ford(n, edges, s=0)
  - n: 頂点数 (0-indexed: 0 ~ n-1)
  - edges: 有向辺リスト [(u, v, weight), ...]
  - s: 始点 (デフォルト 0)
  - 戻り値: (dist, has_neg_cycle)
"""

# https://github.com/ddfkit/acsampl/blob/main/bellman.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def bellman_ford(n,es,s=0,inf=10**18):
    d=[inf]*n;d[s]=0
    for i in range(n):
        up=0
        for u,v,w in es:
            if d[u]<inf and d[u]+w<d[v]:
                d[v]=d[u]+w;up=1
                if i==n-1:return d,True
        if not up:break
    return d,False

if __name__ == "__main__":
    # 始点: [(終点, コスト),...] から辺リスト [(u, v, cost), ...] を作成
    # 頂点数4, 辺: (0->1: 1), (0->2: 4), (1->2: -2), (2->3: 2)
    es = [(0, 1, 1), (0, 2, 4), (1, 2, -2), (2, 3, 2)]
    d, neg = bellman_ford(4, es, 0)
    assert not neg and d == [0, 1, -1, 1]

    # 負閉路が存在するグラフのテスト
    es_neg = [(0, 1, 1), (1, 2, -3), (2, 0, 1)]
    _, neg = bellman_ford(3, es_neg, 0)
    # 負閉路が存在するため neg == True
    assert neg
    print("bellman.py: all tests passed!")
